using docking;
using docking.action;
using docking.action;
using ghidra.app.plugin.core.symboltree;

public abstract class SymbolTreeContextAction : DockingAction {

	protected static readonly string MIDDLE_MENU_GROUP = "0Middle";

	public SymbolTreeContextAction(string name, string owner) : base(name, owner)
    {
	}

	public SymbolTreeContextAction(string name, string owner, KeyBindingType kbType) : base(name, owner, kbType)
    {
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext actionContext) {
		if (!(actionContext is SymbolTreeActionContext)) {
			return false;
		}
		SymbolTreeActionContext context = (SymbolTreeActionContext) actionContext;
		if (context.getProgram() == null) {
			return false;
		}
		return isEnabledForContext(context);
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		actionPerformed((SymbolTreeActionContext) context);
	}

	/* @Override */
	public bool isValidContext(ActionContext context) {
		if (!(context is SymbolTreeActionContext)) {
			return false;
		}
		return isValidContext((SymbolTreeActionContext) context);
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		if (!(context is SymbolTreeActionContext)) {
			return false;
		}
		return isAddToPopup((SymbolTreeActionContext) context);
	}

	protected bool isAddToPopup(SymbolTreeActionContext context) {
		return isEnabledForContext(context);
	}

	protected bool isValidContext(SymbolTreeActionContext context) {
		return true;
	}

	protected bool isEnabledForContext(SymbolTreeActionContext context) {
		TreePath[] selectedSymbolTreePaths = context.getSelectedSymbolTreePaths();
		return selectedSymbolTreePaths != null && selectedSymbolTreePaths.length != 0;
	}

	protected abstract void actionPerformed(SymbolTreeActionContext context);

